style.css:
body {
    background-color: #f3eadf !important;
    color: #3b271d !important;
}

header {
    background-color: #f3eadf !important;
    border-bottom: 1px solid #b99578 !important;
}

nav {
    background-color: #f3eadf !important;
}

/* Headings */
h1,
h2,
h3,
h4,
h5,
h6 {
    color: #4a2c20 !important;
}

/* Links */
a {
    color: #694735 !important;
}

/* Search */
input {
    background-color: #fff9f2 !important;
    color: #4a2c20 !important;
    border: 1px solid #9b7359 !important;
}

input::placeholder {
    color: #927561 !important;
}

/* Buttons */
button {
    background-color: #654331 !important;
    color: #fff8f1 !important;
    border-color: #654331 !important;
}

button:hover {
    background-color: #3b271d !important;
}

/* Article cards */
article {
    background-color: #fffaf4 !important;
}

/* Thin editorial borders */
hr {
    border-color: #c7a990 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 8px !important;
}

::-webkit-scrollbar-track {
    background-color: #eadbcb !important;
}

::-webkit-scrollbar-thumb {
    background-color: #765039 !important;
    border-radius: 8px !important;
}
